"""Prepare the more sculpted, ceremonial revision of the Veil Archon."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]; TOOLS=ROOT/'tools/art_pipeline'
OLD='veil_archon_blocky_v1'; NEW='veil_archon_blocky_v2'
def read(name): return (TOOLS/name).read_text(encoding='utf-8')
def names(s): return s.replace(OLD,NEW).replace('Veil_Archon_Blocky_V1','Veil_Archon_Blocky_V2').replace('VeilArchonModelReview','VeilArchonModelReviewV2')
def write(name,s): (TOOLS/name).write_text(s,encoding='utf-8')
src=read('build_veil_archon_blocky_v1_mcp.py')
head=names(src[:src.index('# A sovereign of folded space:')])
head=head.replace('old_hashes={', "if (ROOT/'assets/generated/grand_manifestations/veil_archon_blocky_v1/veil_archon_blocky_v1.glb').is_file():\n    protected.append(ROOT/'assets/generated/grand_manifestations/veil_archon_blocky_v1/veil_archon_blocky_v1.glb')\nold_hashes={")
uv=src[src.index('coords=[v.co for o in parts for v in o.data.vertices]'):src.index('# Current Arcanist palette')].replace('GROUND=.25','GROUND=.35')
tail=names(src[src.index('images=[]'):]).replace('Ceremonial_Blue_Silver_Azure_Core','Sovereign_Cowl_Folded_Veil_Azure_Core')
tail=tail.replace('Static Veil Archon: faceless open crown, empty broad mantle, exposed azure cube core, floating square hands, suspended veils and four large portal fragments.','Static Veil Archon: exposed azure core in a pointed open cowl, sloped silver ceremonial shoulders, folded midnight-blue mantle, plain square floating hands and a restrained fractured portal.')
tail=tail.replace('Three-meter Veil Archon of Arcanism: empty blue and silver ceremonial mantle, faceless floating crown, broad shoulders, two suspended square hands, exposed azure cube and one fractured dimensional gate. Shared by civilizations.','Three-meter Veil Archon of Arcanism: faceless pointed cowl framing one azure cube, sculpted silver shoulders, folded midnight-blue robe with an irregular floating hem, plain suspended square hands and a darker engraved portal. Shared by civilizations.')
tail=tail.replace('data.ortho_scale=4.6','data.ortho_scale=4.5').replace('(0,0,1.75)','(0,0,1.85)')
write('build_veil_archon_blocky_v2_mcp.py',head+read('veil_archon_v2_geometry.py')+'\n'+uv+read('veil_archon_v2_texture.py')+'\n'+tail)
export=names(read('export_veil_archon_blocky_v1_mcp.py')).replace('abs(low[2]-.25)','abs(low[2]-.35)').replace("'revision':1","'revision':2")
export=export.replace('An empty ceremonial sovereign of folded space: open faceless crown, a broad blue-and-silver mantle, suspended veils and square hands, one exposed azure cube core, four large L-shaped fragments forming a broken dimensional gate.','A ceremonial sovereign of folded space: pointed open cowl framing an exposed azure cube, sculpted silver shoulders, folded midnight-blue robe, an irregular floating hem, plain square hands and a restrained fractured dimensional gate.')
export=export.replace('Single exposed emissive azure cube, separate rigid pivot in a spacious hollow chest','Single exposed emissive azure cube, separate rigid pivot within the pointed open cowl')
write('export_veil_archon_blocky_v2_mcp.py',export)
validator=names(read('validate_veil_archon_blocky_v1.py'))
write('validate_veil_archon_blocky_v2.py',validator)
verify=names(read('verify_veil_archon_blocky_v1.gd')).replace('low.y-.25','low.y-.35').replace('1.75','1.85')
write('verify_veil_archon_blocky_v2.gd',verify)
final=names(read('finalize_veil_archon_blocky_v1_mcp.py')).replace('1.75','1.85')
write('finalize_veil_archon_blocky_v2_mcp.py',final)
review=names((ROOT/'scripts/art_review/VeilArchonModelReview.gd').read_text(encoding='utf-8')).replace('camera.size = 4.6','camera.size = 4.5').replace('1.75','1.85')
(ROOT/'scripts/art_review/VeilArchonModelReviewV2.gd').write_text(review,encoding='utf-8')
scene=names((ROOT/'scenes/art_review/VeilArchonModelReview.tscn').read_text(encoding='utf-8'))
(ROOT/'scenes/art_review/VeilArchonModelReviewV2.tscn').write_text(scene,encoding='utf-8')
gallery=names(read('write_veil_archon_review.py'))
gallery=gallery.replace('Uma entidade flutuante de manto azul e prata, com coroa aberta e mãos suspensas. O núcleo cúbico azul ocupa o peito vazio; quatro grandes fragmentos formam um portal atrás do corpo. A figura traz a identidade do Arcanismo: espaço, teleporte e interferência mágica.','Uma entidade flutuante com capuz aberto, ombros cerimoniais de prata e um manto azul-escuro com dobras e barra irregular. O núcleo cúbico azul ocupa a abertura do capuz; mãos quadradas simples e fragmentos de portal completam sua silhueta. A figura segue a identidade do Arcanismo: espaço, teleporte e interferência mágica.')
gallery=gallery.replace('suspenso 0,25 m','suspenso 0,35 m').replace('Manto cerimonial vazio em azul e prata, coroa sem rosto, mãos quadradas suspensas, núcleo cúbico azul exposto e quatro fragmentos grandes formando um portal dimensional.','Manto azul-escuro com dobras e barra irregular, capuz aberto sem rosto, placas de ombro cerimoniais em prata, mãos quadradas suspensas, núcleo cúbico azul exposto e um portal dimensional fragmentado.')
write('write_veil_archon_v2_review.py',gallery)
write('compare_veil_archon_v2.py',names(read('compare_veil_archon_v1.py')))
print('Sculpted ceremonial Arconte V2 pipeline prepared.')
